/* List view: split pane, grid rows, badges, tiles. Colors come from --aq-* tokens. */

.aq-split {
    display: flex;
    flex: 1;
    min-height: 0;
}

.aq-split-main {
    flex: 1;
    min-width: 0;
    overflow: auto;
    background: var(--aq-surface);
}

.aq-inspector {
    width: 320px;
    flex-shrink: 0;
    overflow: auto;
    border-left: 1px solid var(--aq-border);
    background: var(--aq-background);
    padding: 20px;
    display: flex;
    flex-direction: column;
    gap: 18px;
}

.aq-thead, .aq-tr {
    display: grid;
    align-items: center;
    column-gap: 12px;
    padding: 0 22px;
}

.aq-thead {
    box-sizing: border-box;
    height: 30px;
    position: sticky;
    top: 0;
    z-index: 30;
    font-size: 15px;
}

.aq-tile[data-shape=round] {
    border-radius: 50%;
}

@media (max-width: 1100px) {
    .aq-inspector {
        width: 280px;
    }
}

@media (max-width: 820px) {
    .aq-split {
        flex-direction: column;
        overflow: auto;
    }
    .aq-split-main {
        overflow: visible;
        flex: none;
    }
    .aq-inspector {
        width: auto;
        border-left: 0;
        border-top: 1px solid var(--aq-border);
        overflow: visible;
    }
    .aq-thead, .aq-tr {
        min-width: 640px;
    }
}

.aq-cell-text {
    font-size: 12.5px;
    white-space: nowrap;
